(180042, 10114, 327, '<td valign="top">Her cute, pudgy hand makes this shot for me.....along with the hair. So girl!!! Love the look of this shot. Good work.</td>', 'Her cute, pudgy hand makes this shot for me.....along with the hair. So girl!!! Love the look of this shot. Good work.', '2002-12-30 18:53:29.000000', NULL, 1),
(180043, 10118, 327, '<td valign="top">Good model, good light, tones, focus, and pose. The backdrop has to go!!!!!</td>', 'Good model, good light, tones, focus, and pose. The backdrop has to go!!!!!', '2002-12-30 18:54:18.000000', NULL, 1),
