(180046, 10189, 4225, '<td valign="top">This is totally awesome! Has the look of the a man with alot on his mind. I give this a 9.</td>', 'This is totally awesome! Has the look of the a man with alot on his mind. I give this a 9.', '2002-12-30 18:55:53.000000', NULL, 1),
(180047, 10319, 1202, '<td valign="top">I feel that you have a lot too much back light, due to the loss of part of his ear and arm.   I also would like to see some of the detail hidden by the dark shadows on the right side of his face.</td>', 'I feel that you have a lot too much back light, due to the loss of part of his ear and arm.   I also would like to see some of the detail hidden by the dark shadows on the right side of his face.', '2002-12-30 18:57:56.000000', NULL, 1),
