(180443, 10136, 3724, '<td valign="top">- i am going to see what it looks like printed........   i like it, looks better in print.........   and high score for showing some experimental b&amp;w.  Unique painterly quality - ie. Francis Bacon<br/><br/><i>Message edited by author 2008-01-16 12:28:42.</i></td>', '- i am going to see what it looks like printed........   i like it, looks better in print.........   and high score for showing some experimental b&w.  Unique painterly quality - ie. Francis Bacon', '2002-12-31 11:47:54.000000', '2008-01-16 12:28:42.000000', 1),
(180460, 10213, 5484, '<td valign="top">10</td>', '10', '2002-12-31 12:32:42.000000', NULL, 1),
(180480, 10263, 472, '<td valign="top">quite cute. good composition and frame. good light.  a little unsharp.  the eye on my right is a little dark. overall great effort.</td>', 'quite cute. good composition and frame. good light.  a little unsharp.  the eye on my right is a little dark. overall great effort.', '2002-12-31 13:27:00.000000', NULL, 1),
(180482, 10322, 472, '<td valign="top">cute child. busy background sort of takes away. i would prefer a little more eye contact with camera.</td>', 'cute child. busy background sort of takes away. i would prefer a little more eye contact with camera.', '2002-12-31 13:27:56.000000', NULL, 1),
(180483, 10123, 472, '<td valign="top">interesting composition. good sharpness on the face.</td>', 'interesting composition. good sharpness on the face.', '2002-12-31 13:28:30.000000', NULL, 1),
(180485, 10334, 472, '<td valign="top">this guy is very cute. animals rock :)  i know it''s grainy -- but obviously it''s a crop from a bigger pic.  that said. good job!</td>', 'this guy is very cute. animals rock :)  i know it''s grainy -- but obviously it''s a crop from a bigger pic.  that said. good job!', '2002-12-31 13:29:07.000000', NULL, 1),
(180486, 10309, 472, '<td valign="top">good portrait. all the technicals are right on. as a portrait photographer i would suggest some powder or other things to cover skin blemishes, and maybe an angle that doesnt look up her nose.</td>', 'good portrait. all the technicals are right on. as a portrait photographer i would suggest some powder or other things to cover skin blemishes, and maybe an angle that doesnt look up her nose.', '2002-12-31 13:30:02.000000', NULL, 1),
(180488, 10239, 472, '<td valign="top">great composition.  it''s a little too dark toned for me. you can suggest darkness but still have a full range of photographic tones.</td>', 'great composition.  it''s a little too dark toned for me. you can suggest darkness but still have a full range of photographic tones.', '2002-12-31 13:30:59.000000', NULL, 1),
(180489, 10305, 472, '<td valign="top">a little too high key for me.  the exposure is beyond burned out :).. i like the composition tho.</td>', 'a little too high key for me.  the exposure is beyond burned out :).. i like the composition tho.', '2002-12-31 13:31:38.000000', NULL, 1),
(180490, 10304, 811, '<td valign="top">What a cutie, and talented too!  His parents must be geniuses or sumtin!</td>', 'What a cutie, and talented too!  His parents must be geniuses or sumtin!', '2002-12-31 13:32:07.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(180491, 10326, 472, '<td valign="top">ive seen this guy before.  i bet this is alecia''s shot.  he''s a hunk. this is a good pic.m the only thing i might change is the pose.</td>', 'ive seen this guy before.  i bet this is alecia''s shot.  he''s a hunk. this is a good pic.m the only thing i might change is the pose.', '2002-12-31 13:32:44.000000', NULL, 1),
(180492, 10114, 472, '<td valign="top">very cute. good light.</td>', 'very cute. good light.', '2002-12-31 13:32:57.000000', NULL, 1),
(180493, 10185, 472, '<td valign="top">well isnt he a fuzzy kitty. i like the crop.  overall the pic seems a little gray, and grainy, to me.</td>', 'well isnt he a fuzzy kitty. i like the crop.  overall the pic seems a little gray, and grainy, to me.', '2002-12-31 13:33:38.000000', NULL, 1),
(180494, 10267, 472, '<td valign="top">i like the letter box format.</td>', 'i like the letter box format.', '2002-12-31 13:34:20.000000', NULL, 1),
(180495, 10166, 472, '<td valign="top">very interesting. was this a candid? i feel the cup and such are too closeo to the edge of the frame.</td>', 'very interesting. was this a candid? i feel the cup and such are too closeo to the edge of the frame.', '2002-12-31 13:34:58.000000', NULL, 1),
(180496, 10270, 472, '<td valign="top">what a pretty pretty girl!  good sharpness and light.</td>', 'what a pretty pretty girl!  good sharpness and light.', '2002-12-31 13:35:32.000000', NULL, 1),
(180497, 10153, 472, '<td valign="top">ultra cute! needs a little more DOF so the little girl is sharp too</td>', 'ultra cute! needs a little more DOF so the little girl is sharp too', '2002-12-31 13:35:55.000000', NULL, 1),
(180502, 10150, 3401, '<td valign="top">Great picture Very cute little girl</td>', 'Great picture Very cute little girl', '2002-12-31 13:50:29.000000', NULL, 1),
(180503, 10118, 3401, '<td valign="top">nice</td>', 'nice', '2002-12-31 13:51:23.000000', NULL, 1),
(180504, 10243, 3401, '<td valign="top">Great picture, good detials *9*</td>', 'Great picture, good detials *9*', '2002-12-31 13:52:05.000000', NULL, 1),
(180506, 10183, 3080, '<td valign="top">That upper right corner is so white in comparrison to the rest of the photo that it''s kind of distracting to me.  The portrait it''s self it good.  I realize that with the title, she''s probably suposed to look sad, but I think she would be a very pretty model if smiling too!  The focus is a bit soft, but it does''t bother me, and I actually think it makes the shot nice.  Good luck in the challenge.</td>', 'That upper right corner is so white in comparrison to the rest of the photo that it''s kind of distracting to me.  The portrait it''s self it good.  I realize that with the title, she''s probably suposed to look sad, but I think she would be a very pretty model if smiling too!  The focus is a bit soft, but it does''t bother me, and I actually think it makes the shot nice.  Good luck in the challenge.', '2002-12-31 13:55:22.000000', NULL, 1),
(180507, 10149, 3080, '<td valign="top">I really like how you have done this.  With the black and white ''background''.  The portrait is nice, very nice looking model.  I like the angle and framing/cropping.  The focus and clarity are good, and the lighting is very nice.    The shadow on the dark half (the left) isn''t distracting, but quite noticable.  would probably be hard to tone that down though and still get the same effect.  Great shot. Good luck in the challenge.</td>', 'I really like how you have done this.  With the black and white ''background''.  The portrait is nice, very nice looking model.  I like the angle and framing/cropping.  The focus and clarity are good, and the lighting is very nice.    The shadow on the dark half (the left) isn''t distracting, but quite noticable.  would probably be hard to tone that down though and still get the same effect.  Great shot. Good luck in the challenge.', '2002-12-31 14:00:09.000000', NULL, 1),
(180515, 10123, 3080, '<td valign="top">I would almost like to see a bit more of the face.  The shadow from the door covers up even more than what is ''suposed to be'' covered up.  Your focus and clarity are great though.  Lighting might be a bit harsh on the left half of the door, making the shadow really dark and slightly distracting.  Good luck in the challenge.</td>', 'I would almost like to see a bit more of the face.  The shadow from the door covers up even more than what is ''suposed to be'' covered up.  Your focus and clarity are great though.  Lighting might be a bit harsh on the left half of the door, making the shadow really dark and slightly distracting.  Good luck in the challenge.', '2002-12-31 14:22:55.000000', NULL, 1),
(180517, 10297, 3080, '<td valign="top">With the pattern on the dog being blotchy, the blotchy background is almost a bit too much.  The portrait though is nice.  Good focus and clarity.  Lighting is a bit harsh on the white part of the nose, on the dogs left side of it''s face.  I like the angle and framing/cropping though.  Really emphasizes the dogs face, which is good for a portrait.  Probably getting slack for doing a dog portrait, but I think it''s ok.  Good luck in the challenge.</td>', 'With the pattern on the dog being blotchy, the blotchy background is almost a bit too much.  The portrait though is nice.  Good focus and clarity.  Lighting is a bit harsh on the white part of the nose, on the dogs left side of it''s face.  I like the angle and framing/cropping though.  Really emphasizes the dogs face, which is good for a portrait.  Probably getting slack for doing a dog portrait, but I think it''s ok.  Good luck in the challenge.', '2002-12-31 14:25:25.000000', NULL, 1),
(180519, 10138, 3080, '<td valign="top">The bright area in the upper right is a bit out of place.  I tried this with a crop along that horizontal line that seperates the dark background from the light background, and I think it still works nicely, and also brings the attention down to her pretty face.  Your focus and clarity are good, and the angle is nice as well.  I like the candles in the background.  Great shot. Good luck in the challenge.</td>', 'The bright area in the upper right is a bit out of place.  I tried this with a crop along that horizontal line that seperates the dark background from the light background, and I think it still works nicely, and also brings the attention down to her pretty face.  Your focus and clarity are good, and the angle is nice as well.  I like the candles in the background.  Great shot. Good luck in the challenge.', '2002-12-31 14:29:34.000000', NULL, 1),
(180520, 10329, 3080, '<td valign="top">This shot looks like you have lighting on both sides.  That kind of makes a funny shadow around the nose and eyes.  At first I thought it was an overhead lighting causing shadow from the brim of the hat, but it looks like 2 nose shadows.  I''m not positive how it works, but I''ve seen this kind of thing in other shots, and have seen it suggested that "fill flash" could help.  I don''t have that on my camera, so I dont know how it works, so if I''m wrong, just ignore me.  Otherwise, I really like the portrait.  It''s very respectful looking, and the angle and framing/cropping are good.  Good luck in the challenge.</td>', 'This shot looks like you have lighting on both sides.  That kind of makes a funny shadow around the nose and eyes.  At first I thought it was an overhead lighting causing shadow from the brim of the hat, but it looks like 2 nose shadows.  I''m not positive how it works, but I''ve seen this kind of thing in other shots, and have seen it suggested that "fill flash" could help.  I don''t have that on my camera, so I dont know how it works, so if I''m wrong, just ignore me.  Otherwise, I really like the portrait.  It''s very respectful looking, and the angle and framing/cropping are good.  Good luck in the challenge.', '2002-12-31 14:36:24.000000', NULL, 1),
(180525, 10227, 2337, '<td valign="top">You have a nice composition here, but for my tastes, you went too far with the post processing.  I can see the value in it, but it just doesn''t work for me...</td>', 'You have a nice composition here, but for my tastes, you went too far with the post processing.  I can see the value in it, but it just doesn''t work for me...', '2002-12-31 14:56:09.000000', NULL, 1),
(180526, 10129, 2337, '<td valign="top">This really pushes the border on "portrait"... It seems more appropriate for a "Still Life" challenge... That being said, I really like the composition... The lighting left a few hot-spots, but not overly distracting ones...</td>', 'This really pushes the border on "portrait"... It seems more appropriate for a "Still Life" challenge... That being said, I really like the composition... The lighting left a few hot-spots, but not overly distracting ones...', '2002-12-31 15:04:48.000000', NULL, 1),
(180528, 10186, 2337, '<td valign="top">This is either a very unique interpetation of the challenge, or it just doesn''t meet it... I haven''t decided yet.  The composition seems a tad crowded on the left side...</td>', 'This is either a very unique interpetation of the challenge, or it just doesn''t meet it... I haven''t decided yet.  The composition seems a tad crowded on the left side...', '2002-12-31 15:07:25.000000', NULL, 1),
(180530, 10304, 2337, '<td valign="top">Very interesting composition and nice use of humor... The focus seems a tad softer then necessary and the background lines are pulling my eye off the face and spoon.  Otherwise, I wonderful shot :)</td>', 'Very interesting composition and nice use of humor... The focus seems a tad softer then necessary and the background lines are pulling my eye off the face and spoon.  Otherwise, I wonderful shot :)', '2002-12-31 15:11:32.000000', NULL, 1),
(180531, 10136, 2337, '<td valign="top">This is one of those artistic types of shots that is probably wonderful, but is way over my head.  I can''t score it high (since I don''t like it) but I won''t score it low either, since I can see it to be artistic.</td>', 'This is one of those artistic types of shots that is probably wonderful, but is way over my head.  I can''t score it high (since I don''t like it) but I won''t score it low either, since I can see it to be artistic.', '2002-12-31 15:13:20.000000', NULL, 1),
(180532, 10285, 1280, '<td valign="top">awwwwww....I like it!  3 wonderful faces.</td>', 'awwwwww....I like it!  3 wonderful faces.', '2002-12-31 15:16:45.000000', NULL, 1),
(180534, 10233, 2337, '<td valign="top">I like the composition here, but the focus seems overly soft.  Also, I wonder if the slant of the "horizon" (the table edge) should either be straighter or more dramatically slanted... The slight slant looks more "accidental" then "artistic"... Of course, that\''s just my opinion, and I\''ve been wrong before :)</td>', 'I like the composition here, but the focus seems overly soft.  Also, I wonder if the slant of the "horizon" (the table edge) should either be straighter or more dramatically slanted... The slight slant looks more "accidental" then "artistic"... Of course, that\''s just my opinion, and I\''ve been wrong before :)', '2002-12-31 15:20:39.000000', NULL, 1),
(180557, 10153, 2123, '<td valign="top">oh my GOSH look at those lashes!!  Very cute and nicely framed</td>', 'oh my GOSH look at those lashes!!  Very cute and nicely framed', '2002-12-31 16:44:12.000000', NULL, 1),
(180562, 10124, 3080, '<td valign="top">The bright light/shadow combination on the bird bothers me a bit.  Otherwise, I think the shot is very nice.  The background is not distracting, the focus and clarity are good, and the angle and framing/cropping are good as well.  I like the detail you show us in the beak.  Since I started my job a couple weeks ago, I have gotten the pleasure of working with a couple of these, and they are really fun to work with.  Quite friendly, but don''t make them mad!! Good luck in the challenge.</td>', 'The bright light/shadow combination on the bird bothers me a bit.  Otherwise, I think the shot is very nice.  The background is not distracting, the focus and clarity are good, and the angle and framing/cropping are good as well.  I like the detail you show us in the beak.  Since I started my job a couple weeks ago, I have gotten the pleasure of working with a couple of these, and they are really fun to work with.  Quite friendly, but don''t make them mad!! Good luck in the challenge.', '2002-12-31 17:50:14.000000', NULL, 1),
(180564, 10162, 3080, '<td valign="top">Oh i think this would have been so wonderful, if by chance you could have gotten a shot of him looking up at the music!  I know how hard it is to get them to do anything, really.  I entered my 2 year old this week.  The focus and clarity are really nice.  angle and framing/cropping are good too.  I like how you have captured a moment for this child.  Good luck in the challenge.</td>', 'Oh i think this would have been so wonderful, if by chance you could have gotten a shot of him looking up at the music!  I know how hard it is to get them to do anything, really.  I entered my 2 year old this week.  The focus and clarity are really nice.  angle and framing/cropping are good too.  I like how you have captured a moment for this child.  Good luck in the challenge.', '2002-12-31 17:52:19.000000', NULL, 1),
(180565, 10227, 3080, '<td valign="top">I don''t like this much at all.  There is really no detail to honor this person with.  She looks like a lovely girl, why not show that off?  I can''t comment on technical aspects like focus or lighting, cause there really isn''t any due to so much post processing.  The angle and framing/cropping needs some work though, in my opinion.  You cut her nose right off.  Sorry if I don''t see this the way you do. Good luck in the challenge.</td>', 'I don''t like this much at all.  There is really no detail to honor this person with.  She looks like a lovely girl, why not show that off?  I can''t comment on technical aspects like focus or lighting, cause there really isn''t any due to so much post processing.  The angle and framing/cropping needs some work though, in my opinion.  You cut her nose right off.  Sorry if I don''t see this the way you do. Good luck in the challenge.', '2002-12-31 17:54:25.000000', NULL, 1),
(180568, 10133, 3080, '<td valign="top">Looks like Ben Afflek''s little brother.  I think his name is Cassey.  Anyway, I like the lighting very much.  The dramatic shadow is really cool.  Focus and clarity are good as well.  You show some awesome detail here.  Great angle and framing/cropping.  Good luck in the challenge.</td>', 'Looks like Ben Afflek''s little brother.  I think his name is Cassey.  Anyway, I like the lighting very much.  The dramatic shadow is really cool.  Focus and clarity are good as well.  You show some awesome detail here.  Great angle and framing/cropping.  Good luck in the challenge.', '2002-12-31 17:56:31.000000', NULL, 1),
(180569, 10204, 3080, '<td valign="top">It is uncanny how similar this shot looks to //www.dpchallenge.com/image.php?IMAGE_ID=10012 that shot from the body parts challenge.  It doesn''t really look like the same kid, but I''m wondering.  The one from the body part challenge looks like he''s got a freckle by his mouth, and this one doesn''t, or it''s hidden in the shadow.  I''m curious to know if they are the same, or long lost twins.  About the shot.  Nice job!  The background isn''t distracting, the angle and framing/cropping is great, and the focus and clarity are just awesome.  Really excelent shot.  Good luck in the challenge.</td>', 'It is uncanny how similar this shot looks to //www.dpchallenge.com/image.php?IMAGE_ID=10012 that shot from the body parts challenge.  It doesn''t really look like the same kid, but I''m wondering.  The one from the body part challenge looks like he''s got a freckle by his mouth, and this one doesn''t, or it''s hidden in the shadow.  I''m curious to know if they are the same, or long lost twins.  About the shot.  Nice job!  The background isn''t distracting, the angle and framing/cropping is great, and the focus and clarity are just awesome.  Really excelent shot.  Good luck in the challenge.', '2002-12-31 18:08:59.000000', NULL, 1),
(180584, 10118, 573, '<td valign="top">Nice pose, good lighting and if you would have ironed the background sheet I would have rated this a ten.</td>', 'Nice pose, good lighting and if you would have ironed the background sheet I would have rated this a ten.', '2002-12-31 20:01:38.000000', NULL, 1),
(180611, 10323, 1280, '<td valign="top">This person has an interesting, weathered face.  His attire supports the rugged lifestyle.  Good character image.</td>', 'This person has an interesting, weathered face.  His attire supports the rugged lifestyle.  Good character image.', '2002-12-31 22:43:29.000000', NULL, 1),
(180612, 10162, 1280, '<td valign="top">I love the amused expression on the child''s face.</td>', 'I love the amused expression on the child''s face.', '2002-12-31 22:44:26.000000', NULL, 1),
(180613, 10239, 1280, '<td valign="top">Good close up portrait, with detail.  Nice job!</td>', 'Good close up portrait, with detail.  Nice job!', '2002-12-31 22:54:39.000000', NULL, 1),
(180616, 10224, 1280, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2002-12-31 23:00:50.000000', NULL, 1),
(180618, 10156, 1280, '<td valign="top">Beautiful to see a child laughing.  Great capture!</td>', 'Beautiful to see a child laughing.  Great capture!', '2002-12-31 23:04:46.000000', NULL, 1),
(180619, 10152, 472, '<td valign="top">harsh light makes relaxing angle not comfortable looking</td>', 'harsh light makes relaxing angle not comfortable looking', '2002-12-31 23:05:20.000000', NULL, 1),
