(180708, 10331, 1202, '<td valign="top">For the bright background not bad, but a little more light reflected on your face would have helped the picture quality.  It looks as though you wanted to keep your identity and at the same time share it.   More light!</td>', 'For the bright background not bad, but a little more light reflected on your face would have helped the picture quality.  It looks as though you wanted to keep your identity and at the same time share it.   More light!', '2003-01-01 10:09:17.000000', NULL, 1),
(180709, 10153, 1202, '<td valign="top">Great expressions on thes two.   I sure would have liked you to stop down to get better focus on the girl.   I see that both of them are the subject so they both need to be sharp.</td>', 'Great expressions on thes two.   I sure would have liked you to stop down to get better focus on the girl.   I see that both of them are the subject so they both need to be sharp.', '2003-01-01 10:11:30.000000', NULL, 1),
