(181102, 10305, 5212, '<td valign="top">Nice use of contrast, would have liked a little more contrast in the nose area, otherwise I think it''s a great shot.</td>', 'Nice use of contrast, would have liked a little more contrast in the nose area, otherwise I think it''s a great shot.', '2003-01-02 01:53:08.000000', NULL, 1),
(181103, 10243, 5212, '<td valign="top">Beautiful portrait.  Don''t really understand the title, but that really doesn''t matter, the image is great.  9</td>', 'Beautiful portrait.  Don''t really understand the title, but that really doesn''t matter, the image is great.  9', '2003-01-02 01:54:13.000000', NULL, 1),
