(181105, 10285, 5212, '<td valign="top">Loved this one, gave it a 10.</td>', 'Loved this one, gave it a 10.', '2003-01-02 01:56:49.000000', NULL, 1),
(181106, 10106, 5212, '<td valign="top">Fantastic photo, loved the crop, lighting, composition and clarity.  Also, the expression captured shows something personal and deep about this man.  gave it a 10.</td>', 'Fantastic photo, loved the crop, lighting, composition and clarity.  Also, the expression captured shows something personal and deep about this man.  gave it a 10.', '2003-01-02 01:58:33.000000', NULL, 1),
(181107, 10309, 5212, '<td valign="top">Very nice, great contrast, clarity, lighting ...9</td>', 'Very nice, great contrast, clarity, lighting ...9', '2003-01-02 02:00:58.000000', NULL, 1),
(181108, 10313, 5212, '<td valign="top">Nice quality of image.</td>', 'Nice quality of image.', '2003-01-02 02:01:52.000000', NULL, 1),
(181109, 10156, 5212, '<td valign="top">Great capture of this child.  Might have preferred a bit plainer background.  I also really like the crop and contrast in this photo.</td>', 'Great capture of this child.  Might have preferred a bit plainer background.  I also really like the crop and contrast in this photo.', '2003-01-02 02:03:01.000000', NULL, 1),
