(181114, 10198, 5212, '<td valign="top">Nice portrait of a beautiful child.  Normally I don''t like a "busy" background, but somehow the colors and images in the background add to this portrait.  8</td>', 'Nice portrait of a beautiful child.  Normally I don''t like a "busy" background, but somehow the colors and images in the background add to this portrait.  8', '2003-01-02 02:05:50.000000', NULL, 1),
(181117, 10162, 5212, '<td valign="top">I like what this says about this child and the candid nature of the photo, along with use of contrast and nice soft lighting.</td>', 'I like what this says about this child and the candid nature of the photo, along with use of contrast and nice soft lighting.', '2003-01-02 02:07:19.000000', NULL, 1),
(181119, 10306, 5212, '<td valign="top">This person''s eyes do express him without the rest of his face.  Good job and good luck.</td>', 'This person''s eyes do express him without the rest of his face.  Good job and good luck.', '2003-01-02 02:08:06.000000', NULL, 1),
(181122, 10107, 5212, '<td valign="top">Love the angle and expression in the child''s eyes, along use of humor.</td>', 'Love the angle and expression in the child''s eyes, along use of humor.', '2003-01-02 02:09:25.000000', NULL, 1),
