(181130, 10207, 5212, '<td valign="top">Looks more like self-hatred to me.  Interesting shot.</td>', 'Looks more like self-hatred to me.  Interesting shot.', '2003-01-02 02:13:03.000000', NULL, 1),
(181133, 10124, 5212, '<td valign="top">Great shot, gave it a 9. I love the way the light leads to the eye and the clarity of the bird is really nice.</td>', 'Great shot, gave it a 9. I love the way the light leads to the eye and the clarity of the bird is really nice.', '2003-01-02 02:14:28.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(181134, 10115, 5212, '<td valign="top">Very nice, gave it an 8.</td>', 'Very nice, gave it an 8.', '2003-01-02 02:15:18.000000', NULL, 1),
(181136, 10216, 5212, '<td valign="top">Would like to have seen the hand on right and the face a bit more in focue.</td>', 'Would like to have seen the hand on right and the face a bit more in focue.', '2003-01-02 02:16:03.000000', NULL, 1),
(181139, 10315, 5212, '<td valign="top">GReat shot, gave it a 9.  The only thing I might change is the harsh hightlights in teh eyes.  Beautiful lighting, crop, and contrast.</td>', 'GReat shot, gave it a 9.  The only thing I might change is the harsh hightlights in teh eyes.  Beautiful lighting, crop, and contrast.', '2003-01-02 02:17:14.000000', NULL, 1),
(181140, 10263, 5212, '<td valign="top">One of my favorites.  GAve it a nine.</td>', 'One of my favorites.  GAve it a nine.', '2003-01-02 02:18:53.000000', NULL, 1),
(181143, 10231, 5212, '<td valign="top">One of my favorites, gave it a 9.</td>', 'One of my favorites, gave it a 9.', '2003-01-02 02:19:40.000000', NULL, 1),
(181144, 10130, 5212, '<td valign="top">Title really describes this portrait well.  N ice shot, good luck in teh challenge.</td>', 'Title really describes this portrait well.  N ice shot, good luck in teh challenge.', '2003-01-02 02:20:36.000000', NULL, 1),
(181146, 10281, 5212, '<td valign="top">Wonderful shot.  Would like to see the white line on the sleeve and under the hat eliminated.  gave it a nine.</td>', 'Wonderful shot.  Would like to see the white line on the sleeve and under the hat eliminated.  gave it a nine.', '2003-01-02 02:22:28.000000', NULL, 1),
(181149, 10152, 5212, '<td valign="top">Very nice shot, creative, personal, dof.</td>', 'Very nice shot, creative, personal, dof.', '2003-01-02 02:23:27.000000', NULL, 1),
(181150, 10133, 5212, '<td valign="top">Tells a lot about the subject without revealing the whole face.</td>', 'Tells a lot about the subject without revealing the whole face.', '2003-01-02 02:24:08.000000', NULL, 1),
(181154, 10189, 5212, '<td valign="top">Very good portrayal of this man''s character.  I have no suggestions that would make this photo better. Gave it a 10.</td>', 'Very good portrayal of this man''s character.  I have no suggestions that would make this photo better. Gave it a 10.', '2003-01-02 02:26:30.000000', NULL, 1),
(181155, 10144, 5212, '<td valign="top">Nice shot, interesting use of light and contrast.</td>', 'Nice shot, interesting use of light and contrast.', '2003-01-02 02:27:08.000000', NULL, 1),
(181166, 10296, 4085, '<td valign="top">Just my thoughts, but I would like it better if the neckles was at the bottom of the chain loop.  The portrait is still done very well.</td>', 'Just my thoughts, but I would like it better if the neckles was at the bottom of the chain loop.  The portrait is still done very well.', '2003-01-02 03:12:46.000000', NULL, 1),
(181218, 10313, 1202, '<td valign="top">Nice technically, I don''t care too much for the glasses frame cutting through his eyes.   IMO that takes a lot away.</td>', 'Nice technically, I don''t care too much for the glasses frame cutting through his eyes.   IMO that takes a lot away.', '2003-01-02 08:45:09.000000', NULL, 1),
(181222, 10192, 1202, '<td valign="top">Very good except the item he is sitting on.  It is unusual and it makes one try to guess what it is and distracts my eye from the main subject.   If it were a more common chair or stool then I would have to shut up.</td>', 'Very good except the item he is sitting on.  It is unusual and it makes one try to guess what it is and distracts my eye from the main subject.   If it were a more common chair or stool then I would have to shut up.', '2003-01-02 08:47:53.000000', NULL, 1),
(181223, 10173, 1202, '<td valign="top">One is getting into it and the other one is just putting up with you.   Shows that it may have been spontaneous, but still quite nice.  Good use of DOF.</td>', 'One is getting into it and the other one is just putting up with you.   Shows that it may have been spontaneous, but still quite nice.  Good use of DOF.', '2003-01-02 08:51:23.000000', NULL, 1),
(181225, 10315, 1202, '<td valign="top">The unequal and bright spot in the eyes is distracting to me.   KNowing how hard it is to take a picture of pets, it is otherwisw very good.</td>', 'The unequal and bright spot in the eyes is distracting to me.   KNowing how hard it is to take a picture of pets, it is otherwisw very good.', '2003-01-02 08:53:08.000000', NULL, 1),
(181226, 10130, 1202, '<td valign="top">Very good use of light.  Lots of detail and expression.   Make me want to know what he is thinking.</td>', 'Very good use of light.  Lots of detail and expression.   Make me want to know what he is thinking.', '2003-01-02 08:55:03.000000', NULL, 1),
(181227, 10254, 1202, '<td valign="top">Nice composition but the soft focus leaves it kind of flat for me.  your direct close up also makes her nose more prominate, which doesn''t do justice to your subject.</td>', 'Nice composition but the soft focus leaves it kind of flat for me.  your direct close up also makes her nose more prominate, which doesn''t do justice to your subject.', '2003-01-02 08:57:28.000000', NULL, 1),
(181228, 10146, 1202, '<td valign="top">I assume you mean 35 years of partnership, etc.  His shirt distracts and almost makes me think that he is nearing the end of a 35 year sentence.  Just joking but it is a little much for an endearing shot.  Technically great and best wishes to you both.</td>', 'I assume you mean 35 years of partnership, etc.  His shirt distracts and almost makes me think that he is nearing the end of a 35 year sentence.  Just joking but it is a little much for an endearing shot.  Technically great and best wishes to you both.', '2003-01-02 09:03:15.000000', NULL, 1),
(181229, 10269, 1202, '<td valign="top">Great capture of emotion.  I think I would have cropped closer as her little hand''s motion distracts from her facial expression.   Sometimes we have to be careful and not give the viewer too much to look at.</td>', 'Great capture of emotion.  I think I would have cropped closer as her little hand''s motion distracts from her facial expression.   Sometimes we have to be careful and not give the viewer too much to look at.', '2003-01-02 09:06:17.000000', NULL, 1),
(181231, 10114, 1202, '<td valign="top">Nice profile and good use of light.   Too darn bad about the distracting shapes behind her nose and mouth.</td>', 'Nice profile and good use of light.   Too darn bad about the distracting shapes behind her nose and mouth.', '2003-01-02 09:08:00.000000', NULL, 1),
(181235, 10118, 1202, '<td valign="top">Damn, You good photographers make me jealous.  Good job but a smidge flat.  I think a little more light to make your whites a little stronger to give the image more contrast.   Just guessing!</td>', 'Damn, You good photographers make me jealous.  Good job but a smidge flat.  I think a little more light to make your whites a little stronger to give the image more contrast.   Just guessing!', '2003-01-02 09:13:00.000000', NULL, 1),
(181236, 10270, 1202, '<td valign="top">Is that Santa''s beard that she has just torn up down in front of her?   Between that and the background I have a hard time concentrating on the very excellent image of Lili.</td>', 'Is that Santa''s beard that she has just torn up down in front of her?   Between that and the background I have a hard time concentrating on the very excellent image of Lili.', '2003-01-02 09:15:34.000000', NULL, 1),
(181237, 10112, 1202, '<td valign="top">Nice shot, the bannister and stair rails compliment the subject in this composition.   I think a little more contrast would help it pop.   Don''t ever do anything to make your model camera shy as she is great.  If she is you, then stay in control!</td>', 'Nice shot, the bannister and stair rails compliment the subject in this composition.   I think a little more contrast would help it pop.   Don''t ever do anything to make your model camera shy as she is great.  If she is you, then stay in control!', '2003-01-02 09:20:08.000000', NULL, 1),
(181238, 10129, 1202, '<td valign="top">One thing for sure you didn''t have any trouble getting him to stay still.  I think a little smile would have helped though.  Nice everything else.</td>', 'One thing for sure you didn''t have any trouble getting him to stay still.  I think a little smile would have helped though.  Nice everything else.', '2003-01-02 09:22:24.000000', NULL, 1),
(181239, 10224, 1202, '<td valign="top">I think a nice close srop to bring out the love in the womans eyes would enhance your shot.  The white of the cat kind of overpowers  the rest of the picture.</td>', 'I think a nice close srop to bring out the love in the womans eyes would enhance your shot.  The white of the cat kind of overpowers  the rest of the picture.', '2003-01-02 09:25:05.000000', NULL, 1),
(181240, 10123, 1202, '<td valign="top">Neat idea and good result.   I think a little more hinge so we don''t have to figure out what it is, or no hinge at all.   It starts to take on a whole different look as I scroll it up getting rid of the hinge.</td>', 'Neat idea and good result.   I think a little more hinge so we don''t have to figure out what it is, or no hinge at all.   It starts to take on a whole different look as I scroll it up getting rid of the hinge.', '2003-01-02 09:29:53.000000', NULL, 1),
(181241, 10117, 1202, '<td valign="top">I can tell she is a nice lady from this shot.   Good use of light and nice contrast.   I am a little bothered by the bright spot on the upper left window frame.   Good job though.</td>', 'I can tell she is a nice lady from this shot.   Good use of light and nice contrast.   I am a little bothered by the bright spot on the upper left window frame.   Good job though.', '2003-01-02 09:33:02.000000', NULL, 1),
(181242, 10124, 1202, '<td valign="top">Excellent!</td>', 'Excellent!', '2003-01-02 09:33:56.000000', NULL, 1),
(181244, 10213, 1202, '<td valign="top">Sofia, has a million dollar dimple and smile.   I''ll bet this is a posed shot, so why is there a hair crossing her forehead?   The closed eyes add wonderfully to your composition, good job.   Great use of DOF.</td>', 'Sofia, has a million dollar dimple and smile.   I''ll bet this is a posed shot, so why is there a hair crossing her forehead?   The closed eyes add wonderfully to your composition, good job.   Great use of DOF.', '2003-01-02 09:38:32.000000', NULL, 1),
(181245, 10108, 1202, '<td valign="top">Nice human form shot but as a portrait I am not impressed.</td>', 'Nice human form shot but as a portrait I am not impressed.', '2003-01-02 09:39:57.000000', NULL, 1),
(181246, 10239, 1202, '<td valign="top">Your shot shows a lot of enmotion, I hope he will be okay.   Well balanced picture and good use of minimal light.</td>', 'Your shot shows a lot of enmotion, I hope he will be okay.   Well balanced picture and good use of minimal light.', '2003-01-02 09:41:32.000000', NULL, 1),
(181248, 10305, 1202, '<td valign="top">Outstanding picture, great retention of detail while blowing out a lot of the subject.</td>', 'Outstanding picture, great retention of detail while blowing out a lot of the subject.', '2003-01-02 09:45:09.000000', NULL, 1),
(181254, 10118, 3506, '<td valign="top">The sharply-focused wrinkles in the backdrop distract from the subject.  But this is an excellent photograph overall.  (9)</td>', 'The sharply-focused wrinkles in the backdrop distract from the subject.  But this is an excellent photograph overall.  (9)', '2003-01-02 09:59:31.000000', NULL, 1),
(181330, 10223, 472, '<td valign="top">i like the lighting and the tones.  i wish the models facial expression wasnt so bored or apathetic : ) .. focus could be a hair sharper...</td>', 'i like the lighting and the tones.  i wish the models facial expression wasnt so bored or apathetic : ) .. focus could be a hair sharper...', '2003-01-02 13:09:56.000000', NULL, 1),
(181331, 10107, 472, '<td valign="top">hilarious :)</td>', 'hilarious :)', '2003-01-02 13:12:41.000000', NULL, 1),
(181333, 10130, 472, '<td valign="top">excellent work. the lighting, sharpness and pose on this are nearly perfect.</td>', 'excellent work. the lighting, sharpness and pose on this are nearly perfect.', '2003-01-02 13:15:12.000000', NULL, 1),
(181334, 10221, 472, '<td valign="top">for real?</td>', 'for real?', '2003-01-02 13:17:49.000000', NULL, 1),
(181341, 10119, 3846, '<td valign="top">Good picture</td>', 'Good picture', '2003-01-02 14:05:54.000000', NULL, 1),
(181342, 10166, 2553, '<td valign="top">An interesting character, and an intriguing photo.  I think I would have probably focused more on him  by cropping  out the couple at the table behind him, however, overall, I do like the photo.</td>', 'An interesting character, and an intriguing photo.  I think I would have probably focused more on him  by cropping  out the couple at the table behind him, however, overall, I do like the photo.', '2003-01-02 14:07:57.000000', NULL, 1),
(181343, 10162, 2553, '<td valign="top">Cute shot; well composed with good lighting. I think it would have had more impact for me if he was either looking at the camera, or looking at the sheet music.</td>', 'Cute shot; well composed with good lighting. I think it would have had more impact for me if he was either looking at the camera, or looking at the sheet music.', '2003-01-02 14:09:26.000000', NULL, 1),
(181344, 10150, 2553, '<td valign="top">Cute shot; a little small, and also a little dark for my taste.  I would love to have seen more of a closeup, and morelight on her face.   She looks almost lost amid all that "equipment".</td>', 'Cute shot; a little small, and also a little dark for my taste.  I would love to have seen more of a closeup, and morelight on her face.   She looks almost lost amid all that "equipment".', '2003-01-02 14:11:24.000000', NULL, 1),
(181345, 10204, 2553, '<td valign="top">This shot looks very familiar.  Nice close up shot, I would have preferred the background to be totally black.  (On my monitor, I can see some shapes, and some lighter areas in the background that are a little distracting. )</td>', 'This shot looks very familiar.  Nice close up shot, I would have preferred the background to be totally black.  (On my monitor, I can see some shapes, and some lighter areas in the background that are a little distracting. )', '2003-01-02 14:13:17.000000', NULL, 1),
(181348, 10324, 5955, '<td valign="top">Just Beautifull , i like the light reflect on the moustaches 1</td>', 'Just Beautifull , i like the light reflect on the moustaches 1', '2003-01-02 14:30:09.000000', NULL, 1),
(181349, 10243, 5956, '<td valign="top">Hypnotically beautiful.</td>', 'Hypnotically beautiful.', '2003-01-02 14:30:50.000000', NULL, 1),
(181399, 10244, 2553, '<td valign="top">Good contrast and lighting, and I like the nice tight composition.</td>', 'Good contrast and lighting, and I like the nice tight composition.', '2003-01-02 16:56:56.000000', NULL, 1),
(181401, 10118, 2553, '<td valign="top">She looks like she''s used to this!  Nice lighting, I''m envious.  Not crazy about the wide border, but not voting down for it.</td>', 'She looks like she''s used to this!  Nice lighting, I''m envious.  Not crazy about the wide border, but not voting down for it.', '2003-01-02 16:58:59.000000', NULL, 1),
(181403, 10309, 2553, '<td valign="top">Beautiful lighting and a beautiful shot, but I am sure not crazy about the wide white border.</td>', 'Beautiful lighting and a beautiful shot, but I am sure not crazy about the wide white border.', '2003-01-02 17:00:07.000000', NULL, 1),
(181406, 10324, 2553, '<td valign="top">I like the close up, but the photo, overall, is much too dark for my taste.  I would love to see more light on the cat''s face.  The whiskers do look pretty cool in this shot though.</td>', 'I like the close up, but the photo, overall, is much too dark for my taste.  I would love to see more light on the cat''s face.  The whiskers do look pretty cool in this shot though.', '2003-01-02 17:02:19.000000', NULL, 1),
(181409, 10138, 2553, '<td valign="top">I love the shot, but it would have had much more impact for me if it had been cropped below the light that is just right of center in the top area (I cropped right at the light horizontal line that I see there below the light)- I find that whole top area to be very distracting.  However, when I cropped it, I loved the way her face looks against the neg spc area with the small lights.  Can''t figure out her hair - almost looks like glitter or something on it.</td>', 'I love the shot, but it would have had much more impact for me if it had been cropped below the light that is just right of center in the top area (I cropped right at the light horizontal line that I see there below the light)- I find that whole top area to be very distracting.  However, when I cropped it, I loved the way her face looks against the neg spc area with the small lights.  Can''t figure out her hair - almost looks like glitter or something on it.', '2003-01-02 17:06:49.000000', NULL, 1),
(181429, 10227, 4267, '<td valign="top">seems more like digital art than photography</td>', 'seems more like digital art than photography', '2003-01-02 17:43:14.000000', NULL, 1),
(181432, 10107, 4267, '<td valign="top">lol thats pretty funny... nice lighting contrast</td>', 'lol thats pretty funny... nice lighting contrast', '2003-01-02 17:46:41.000000', NULL, 1),
(181433, 10269, 4267, '<td valign="top">very nice... good focus and contrast... a smaller crop so we don''t see the blurry hands would help even more</td>', 'very nice... good focus and contrast... a smaller crop so we don''t see the blurry hands would help even more', '2003-01-02 17:47:37.000000', NULL, 1),
(181434, 10275, 4267, '<td valign="top">crop some of that un used space out of the shot...</td>', 'crop some of that un used space out of the shot...', '2003-01-02 17:49:40.000000', NULL, 1),
(181454, 10304, 4007, '<td valign="top">The soft focus is a little bit much for me.  It''s a cute shot that is cropped well.  A little more contrast with the background might have been a slight improvement. 6</td>', 'The soft focus is a little bit much for me.  It''s a cute shot that is cropped well.  A little more contrast with the background might have been a slight improvement. 6', '2003-01-02 18:17:48.000000', NULL, 1),
(181461, 10106, 4007, '<td valign="top">I like the straight on shot, the wide eyes, the tight crop/framing, and of course the hood with it''s shadows.  I really enjoy this one. 8</td>', 'I like the straight on shot, the wide eyes, the tight crop/framing, and of course the hood with it''s shadows.  I really enjoy this one. 8', '2003-01-02 18:21:11.000000', NULL, 1),
(181476, 10149, 4338, '<td valign="top">great shot....nice lighting, but maye a tad too dark on her head on the left side of the image....also i wonder how it would look if the mirror was angled a little more....the top more toards the left and the bottom more towards the right</td>', 'great shot....nice lighting, but maye a tad too dark on her head on the left side of the image....also i wonder how it would look if the mirror was angled a little more....the top more toards the left and the bottom more towards the right', '2003-01-02 18:27:44.000000', NULL, 1),
(181480, 10281, 4338, '<td valign="top">very cute picture...nice job</td>', 'very cute picture...nice job', '2003-01-02 18:29:45.000000', NULL, 1),
(181491, 10243, 4338, '<td valign="top">i like this shot....the cropping and the veil adds some mystery to the image.....</td>', 'i like this shot....the cropping and the veil adds some mystery to the image.....', '2003-01-02 18:34:29.000000', NULL, 1),
(181510, 10243, 772, '<td valign="top">beautiful shot :)  The only thing that I believe would make this stronger would be a dark veil... great work :) - setzler</td>', 'beautiful shot :)  The only thing that I believe would make this stronger would be a dark veil... great work :) - setzler', '2003-01-02 18:43:50.000000', NULL, 1),
(181512, 10106, 772, '<td valign="top">best of show = 10 - setzler</td>', 'best of show = 10 - setzler', '2003-01-02 18:44:21.000000', NULL, 1),
(181532, 10146, 772, '<td valign="top">very nice job on this one... a very endearing photo.. good work :) - setzler</td>', 'very nice job on this one... a very endearing photo.. good work :) - setzler', '2003-01-02 18:57:28.000000', NULL, 1),
(181533, 10326, 772, '<td valign="top">Too bad he''s not as hot as i am :)  great shot... = 9 - setzler</td>', 'Too bad he''s not as hot as i am :)  great shot... = 9 - setzler', '2003-01-02 18:57:56.000000', NULL, 1),
(181534, 10245, 772, '<td valign="top">This image has a very nice sort of mystery to it.. i love the look and her big eyes... I think the only thing that bugs me on this a little is the negative space in the top of the frame... I may like this particular shot better if some, but not all, of that was cropped out... great shot.. = 9 - setzler</td>', 'This image has a very nice sort of mystery to it.. i love the look and her big eyes... I think the only thing that bugs me on this a little is the negative space in the top of the frame... I may like this particular shot better if some, but not all, of that was cropped out... great shot.. = 9 - setzler', '2003-01-02 18:59:29.000000', NULL, 1),
(181535, 10152, 772, '<td valign="top">very nice shot... i love the even tones across your subject in this one... the only thing that is possibly an area for improvement woudl be to either have her eyes all the way open or all the way closed.  The model''s right eye (viewer''s left eye) is also significantly darker than the other... maybe a minor change in lighting or a bounce flash from above would even that out some... very good work.. = 9 - setzler</td>', 'very nice shot... i love the even tones across your subject in this one... the only thing that is possibly an area for improvement woudl be to either have her eyes all the way open or all the way closed.  The model''s right eye (viewer''s left eye) is also significantly darker than the other... maybe a minor change in lighting or a bounce flash from above would even that out some... very good work.. = 9 - setzler', '2003-01-02 19:01:29.000000', NULL, 1),
(181557, 10198, 1202, '<td valign="top">The background doesn''t help show off your beautiful model.   Try something that is less distracting or move her out from the wall so a shallow depth of field will blur the background.   At least that''s my opinion.</td>', 'The background doesn''t help show off your beautiful model.   Try something that is less distracting or move her out from the wall so a shallow depth of field will blur the background.   At least that''s my opinion.', '2003-01-02 19:47:54.000000', NULL, 1),
(181599, 10124, 4793, '<td valign="top">I like your photo, good composition. Happy New Year.</td>', 'I like your photo, good composition. Happy New Year.', '2003-01-02 21:31:54.000000', NULL, 1),
(181602, 10153, 4793, '<td valign="top">Little dolls, nice</td>', 'Little dolls, nice', '2003-01-02 21:34:40.000000', NULL, 1),
(181619, 10152, 2553, '<td valign="top">This shot looks a little odd to me - it looks like she is floating in the air or something.</td>', 'This shot looks a little odd to me - it looks like she is floating in the air or something.', '2003-01-02 22:41:38.000000', NULL, 1),
(181620, 10155, 2553, '<td valign="top">Nice shot; nice lighting and composition.</td>', 'Nice shot; nice lighting and composition.', '2003-01-02 22:42:24.000000', NULL, 1),
(181646, 10166, 4648, '<td valign="top">I love the moustache.  I know this can''t be you.  And I love the building it is in.  Tis must be a restaurant that has the times theme.  The focus if fantastic and I love the cropping, with the customers in the back.  Adds authenticity to his outfit and moustache.  Where in the world is this place?  This is an awesome photo and would definitely be a 9 in my book.  PTL</td>', 'I love the moustache.  I know this can''t be you.  And I love the building it is in.  Tis must be a restaurant that has the times theme.  The focus if fantastic and I love the cropping, with the customers in the back.  Adds authenticity to his outfit and moustache.  Where in the world is this place?  This is an awesome photo and would definitely be a 9 in my book.  PTL', '2003-01-02 23:29:33.000000', NULL, 1),
(181652, 10319, 772, '<td valign="top">Very nice high key work.. the shadows and light work with great strength in this image.. the black shirt creates perfect contrast.  The only thing I would change here would be to crop a thin slice off the left to remove whatever that is that is creating the ''edge contrast''... great shot.. = 9 - setzler</td>', 'Very nice high key work.. the shadows and light work with great strength in this image.. the black shirt creates perfect contrast.  The only thing I would change here would be to crop a thin slice off the left to remove whatever that is that is creating the ''edge contrast''... great shot.. = 9 - setzler', '2003-01-02 23:49:03.000000', NULL, 1),
(181653, 10322, 772, '<td valign="top">Children are great subjects for photographs.  I think this particular shot would be much stronger (as would be with most child shots) if it was taken from a lower angle.  Adults seem to naturally want to point the camera down at children.  This seems to accent the fact that they are small.  Your image impact could change dramatically if you shoot from the same level as the child, or even below level :) - setzler</td>', 'Children are great subjects for photographs.  I think this particular shot would be much stronger (as would be with most child shots) if it was taken from a lower angle.  Adults seem to naturally want to point the camera down at children.  This seems to accent the fact that they are small.  Your image impact could change dramatically if you shoot from the same level as the child, or even below level :) - setzler', '2003-01-02 23:52:07.000000', NULL, 1),
(181666, 10115, 2079, '<td valign="top">This is GREAT work. It has a very Biblical style to it. This is an unusual angle for a portrait and it works so well here. Nice style, nice to see this in the challenge. 10 - Gotcha</td>', 'This is GREAT work. It has a very Biblical style to it. This is an unusual angle for a portrait and it works so well here. Nice style, nice to see this in the challenge. 10 - Gotcha', '2003-01-03 01:01:03.000000', NULL, 1),
(181668, 10213, 5966, '<td valign="top">This picture is very nice! It must be the winner.<br/></td>', 'This picture is very nice! It must be the winner.', '2003-01-03 01:13:18.000000', NULL, 1),
(181672, 10213, 2079, '<td valign="top">A beautiful subject, but I\''m dying to see her eyes. I\''d love to see more of her hair on the right side too. The lighting, highlights, midtones, everything very well done. (Wanting to see more, often times can make a better picture by leaving something to the imagination) - this is one of my 10\''s this week - Gotcha</td>', 'A beautiful subject, but I\''m dying to see her eyes. I\''d love to see more of her hair on the right side too. The lighting, highlights, midtones, everything very well done. (Wanting to see more, often times can make a better picture by leaving something to the imagination) - this is one of my 10\''s this week - Gotcha', '2003-01-03 01:16:57.000000', NULL, 1),
(181674, 10118, 2079, '<td valign="top">What a doll. Great expression. I dont care to much for the background, I think the wrinkles take a little away from the subject, but the subject is powerful enough to keep my eye off the background most of the time. I would also NOT crop the elbow (petty, but bothersome). Over-all, I love the shot 9- Gotcha</td>', 'What a doll. Great expression. I dont care to much for the background, I think the wrinkles take a little away from the subject, but the subject is powerful enough to keep my eye off the background most of the time. I would also NOT crop the elbow (petty, but bothersome). Over-all, I love the shot 9- Gotcha', '2003-01-03 01:27:53.000000', NULL, 1),
(181680, 10136, 2279, '<td valign="top">I think that a portrait should show some detail and something of the person''s personality. This is a very abstract shot and abstract photography is my favorite but I don''t think that it really fits here. All I can really see is one closed eye and a mustache.</td>', 'I think that a portrait should show some detail and something of the person''s personality. This is a very abstract shot and abstract photography is my favorite but I don''t think that it really fits here. All I can really see is one closed eye and a mustache.', '2003-01-03 02:15:35.000000', NULL, 1),
