(181841, 10155, 4617, '<td valign="top">WOW, what a beautiful shot. I give it a 9</td>', 'WOW, what a beautiful shot. I give it a 9', '2003-01-03 12:09:19.000000', NULL, 1),
(181896, 10189, 4055, '<td valign="top">I like this. Cropping, lighting and focus are all good. There´s something in the background that is a little disturbing. Anyway a great portrait and high score from me.</td>', 'I like this. Cropping, lighting and focus are all good. There´s something in the background that is a little disturbing. Anyway a great portrait and high score from me.', '2003-01-03 13:19:25.000000', NULL, 1),
(181899, 10192, 4055, '<td valign="top">I like this portrait. It´s rather relaxed. Good lighting and focus. High score from Sweden.</td>', 'I like this portrait. It´s rather relaxed. Good lighting and focus. High score from Sweden.', '2003-01-03 13:22:32.000000', NULL, 1),
(181903, 10281, 4055, '<td valign="top">Nice portrait. Good lighting and focus. The contrast is a little bit high for my taste but that´s because I´m fond of more graytones. No big deal. High score anyway.</td>', 'Nice portrait. Good lighting and focus. The contrast is a little bit high for my taste but that´s because I´m fond of more graytones. No big deal. High score anyway.', '2003-01-03 13:26:16.000000', NULL, 1),
