(181966, 10315, 2130, '<td valign="top">very good, the clarity is amazing -10</td>', 'very good, the clarity is amazing -10', '2003-01-03 15:18:52.000000', NULL, 1),
(181969, 10203, 2130, '<td valign="top">I like this one, it has something special going for it, it´s like u have captured the soal of this handyman.  It is casual and doesn´t seem too forced or posed.  It would look more dramatic if the background wasn´t in focus or darker or both...but still I like this one enough to give it a 10</td>', 'I like this one, it has something special going for it, it´s like u have captured the soal of this handyman.  It is casual and doesn´t seem too forced or posed.  It would look more dramatic if the background wasn´t in focus or darker or both...but still I like this one enough to give it a 10', '2003-01-03 15:25:26.000000', NULL, 1),
