(181972, 10213, 2130, '<td valign="top">beautiful girl, beautiful photo, looks unposed and natural, congrats :) surely a 10</td>', 'beautiful girl, beautiful photo, looks unposed and natural, congrats :) surely a 10', '2003-01-03 15:27:10.000000', NULL, 1),
